questions.answer:
total = 0
count = 0
passed = 0

while True:
    score = int(input())

    if score == -1:
        break
    if score < 0 or score > 100:
        continue

    total += score
    count += 1
    if score >= 60:
        passed += 1

if count == 0:
    print("No data")
else:
    print(f"Count: {count}")
    print(f"Passed: {passed}")
    print(f"Average: {total / count:.2f}")
